<?php
if(!isset($db)){http_response_code(404);exit;}
function premiumSetup(){
q("CREATE TABLE IF NOT EXISTS onb_agent_targets(agent_id INT NOT NULL,month_key CHAR(7) NOT NULL,target INT NOT NULL,PRIMARY KEY(agent_id,month_key)) ENGINE=InnoDB");
q("CREATE TABLE IF NOT EXISTS onb_instalments(id INT AUTO_INCREMENT PRIMARY KEY,booking_id INT NOT NULL,due DATE NOT NULL,amount DECIMAL(12,2) NOT NULL) ENGINE=InnoDB");
q("CREATE TABLE IF NOT EXISTS onb_reviews(booking_id INT PRIMARY KEY,user_id INT NOT NULL,rating INT NOT NULL,body TEXT NOT NULL,approved TINYINT NOT NULL DEFAULT 0) ENGINE=InnoDB");
q("CREATE TABLE IF NOT EXISTS onb_wishlist(user_id INT NOT NULL,trip_id INT NOT NULL,PRIMARY KEY(user_id,trip_id)) ENGINE=InnoDB");
}
function premiumAction($action,$u,$admin){global $db;if(!$u)throw new RuntimeException('Sign in required.');premiumSetup();
if($action==='premium_target'&&!$admin&&agentActive($u['id'])){$n=filter_var(p('target'),FILTER_VALIDATE_INT,['options'=>['min_range'=>1,'max_range'=>10000]]);if(!$n)throw new RuntimeException('Invalid target.');q('INSERT INTO onb_agent_targets VALUES(?,?,?) ON DUPLICATE KEY UPDATE target=VALUES(target)',[$u['id'],date('Y-m'),$n]);go('page=agentstudio');}
if($action==='premium_instalment'&&$admin){bookingSetup();$id=(int)p('id');$amount=bookingAmount('amount');$date=depDate('due');$db->beginTransaction();try{$b=q('SELECT price FROM onb_bookings WHERE id=? FOR UPDATE',[$id])->fetchColumn();$sum=q('SELECT COALESCE(SUM(amount),0) FROM onb_instalments WHERE booking_id=?',[$id])->fetchColumn();if(!$b||round((float)$sum+(float)$amount,2)>(float)$b)throw new RuntimeException('Schedule exceeds booking total.');q('INSERT INTO onb_instalments(booking_id,due,amount) VALUES(?,?,?)',[$id,$date,$amount]);$db->commit();}catch(Throwable $e){$db->rollBack();throw $e;}go('page=financecentre');}
if($action==='premium_review'&&!$admin){bookingSetup();$id=(int)p('id');$rating=(int)p('rating');if($rating<1||$rating>5||!p('body')||strlen(p('body'))>2000||!q("SELECT id FROM onb_bookings WHERE id=? AND user_id=? AND stage='completed'",[$id,$u['id']])->fetchColumn())throw new RuntimeException('Only completed travellers may review.');q('INSERT INTO onb_reviews VALUES(?,?,?,?,0) ON DUPLICATE KEY UPDATE rating=VALUES(rating),body=VALUES(body),approved=0',[$id,$u['id'],$rating,p('body')]);go('page=travelspace');}
if($action==='premium_moderate'&&$admin){q('UPDATE onb_reviews SET approved=? WHERE booking_id=?',[p('approve')==='1'?1:0,(int)p('id')]);go('page=marketingcentre');}
if($action==='premium_save'&&!$admin){$id=(int)p('id');if(!q('SELECT id FROM trips WHERE id=? AND published=1',[$id])->fetchColumn())throw new RuntimeException('Journey unavailable.');if(p('remove')==='1')q('DELETE FROM onb_wishlist WHERE user_id=? AND trip_id=?',[$u['id'],$id]);else q('INSERT IGNORE INTO onb_wishlist VALUES(?,?)',[$u['id'],$id]);go('page=travelspace');}
throw new RuntimeException('Access denied.');}
function premiumHero($title,$body){echo '<div class="dash-hero"><h1>'.h($title).'</h1><p>'.h($body).'</p></div>';}
function premiumLink($url,$label){echo '<p><a class="btn" href="'.h($url).'">'.h($label).'</a></p>';}
function premiumAgent($u,$admin){global $c;if(!$u||(!$admin&&!agentActive($u['id']))){echo '<p>Agent access required.</p>';return;}premiumSetup();agentSetup();premiumHero('Agent studio','Referral tools, goals and commission planning.');if($admin){premiumLink('?page=agents','Manage agents');return;}$id=$u['id'];$code=q('SELECT code FROM onb_agents WHERE user_id=?',[$id])->fetchColumn();$url=($c['public_url']??'').'?ref='.rawurlencode($code);echo '<article><h2>Your referral link</h2><p>'.h($url).'</p><p>Share your link with prospective travellers. Final pricing and availability are confirmed by the team.</p></article>';
$month=date('Y-m');$target=(int)q('SELECT target FROM onb_agent_targets WHERE agent_id=? AND month_key=?',[$id,$month])->fetchColumn();$sales=(int)q("SELECT COUNT(*) FROM onb_agent_sales WHERE agent_id=? AND DATE_FORMAT(verified_at,'%Y-%m')=?",[$id,$month])->fetchColumn();$year=(int)q('SELECT COUNT(*) FROM onb_agent_sales WHERE agent_id=? AND sale_year=?',[$id,agentYear()])->fetchColumn();$forecast=0;for($i=1;$i<=max(0,$target-$sales);$i++)$forecast+=agentTierRate($year+$i);echo '<div class="metrics"><article>Verified this month<strong>'.h($sales).'</strong></article><article>Monthly target<strong>'.h($target).'</strong></article><article>Potential additional commission<strong>CAD '.number_format($forecast,2).'</strong></article></div>';form('premium_target');field('target','Monthly verified sales target',(string)max(1,$target),'number');echo '<button>Save target</button></form><h2>Marketing kit</h2>';foreach(q('SELECT id,title,route FROM trips WHERE published=1') as $t){echo '<article><h3>'.h($t['title']).'</h3><p>'.h($t['route']).'</p><p>Explore this curated group journey with Our Next Boarding. Contact us for availability and a personalized quotation.</p><p>'.h(($c['public_url']??'').'?page=trip&id='.$t['id'].'&ref='.rawurlencode($code)).'</p></article>';}echo '<h2>Agent training</h2><p>Qualify dates, budget and traveller count. Share published inclusions and trip-specific terms. Never guarantee visas, availability or refunds. Submit leads through your agent workspace. Commissions require verified eligible sales.</p>';premiumLink('?page=agent_statement','Commission statement');}
function premiumFinance($u,$admin){if(!$admin){echo '<p>Access denied.</p>';return;}premiumSetup();bookingSetup();premiumHero('Finance centre','Booking ledger, instalments and supplier costs.');premiumLink('?page=finance_export','Export booking transactions CSV');premiumLink('?page=bookings','Record payments, refunds and expenses');foreach(q('SELECT b.*,t.title FROM onb_bookings b JOIN trips t ON t.id=b.trip_id ORDER BY b.id DESC') as $b){$net=bookingNet($b['id']);echo '<details><summary>'.h($b['ref'].' · '.$b['title']).'</summary><p>Total CAD '.h($b['price']).' · Net paid CAD '.number_format($net,2).' · Balance CAD '.number_format(max(0,$b['price']-$net),2).'</p>';premiumLink('?page=booking_document&id='.$b['id'],'Printable statement');foreach(q('SELECT * FROM onb_instalments WHERE booking_id=? ORDER BY due,id',[$b['id']]) as $i)echo '<p>'.h($i['due']).' · CAD '.h($i['amount']).'</p>';form('premium_instalment');echo '<input type="hidden" name="id" value="'.h($b['id']).'">';field('due','Due date','','date');field('amount','Instalment CAD');echo '<button>Add instalment</button></form></details>';}echo '<h2>Recorded supplier and trip expenses</h2>';foreach(q('SELECT e.*,t.title FROM onb_booking_expenses e JOIN trips t ON t.id=e.trip_id ORDER BY e.id DESC') as $e)echo '<article>'.h($e['title'].' · '.$e['category'].' · '.$e['reference'].' · CAD '.$e['amount']).'</article>';}
function premiumExport($admin){if(!$admin){http_response_code(403);exit;}bookingSetup();header('Content-Type: text/csv');header('Content-Disposition: attachment; filename="booking-transactions.csv"');$f=fopen('php://output','w');fputcsv($f,['Booking','Date','Type','CAD','Reference']);foreach(q('SELECT b.ref,m.created_at,m.kind,m.amount,m.reference FROM onb_booking_money m JOIN onb_bookings b ON b.id=m.booking_id ORDER BY m.id') as $r){$row=[];foreach(array_values(array_intersect_key($r,array_flip(['ref','created_at','kind','amount','reference']))) as $v){$v=(string)$v;$row[]=preg_match('/^[=+@\-\t\r\n]/',$v)?"'".$v:$v;}fputcsv($f,$row);}fclose($f);exit;}
function premiumMarketing($admin){if(!$admin){echo '<p>Access denied.</p>';return;}premiumSetup();premiumHero('Marketing centre','Manage verified reviews and existing campaigns.');premiumLink('?page=growth','Discounts and marketing analytics');premiumLink('?page=travelhub','Email campaigns');foreach(q('SELECT r.*,t.title FROM onb_reviews r JOIN onb_bookings b ON b.id=r.booking_id JOIN trips t ON t.id=b.trip_id') as $r){echo '<article><h3>'.h($r['title'].' · '.$r['rating'].'/5').'</h3><p>'.h($r['body']).'</p>';form('premium_moderate');echo '<input type="hidden" name="id" value="'.h($r['booking_id']).'"><select name="approve"><option value="1">Publish</option><option value="0">Hide</option></select><button>Save moderation</button></form></article>';}}
function premiumTravel($u,$admin){if(!$u||$admin){echo '<p>Traveller sign-in required.</p>';return;}premiumSetup();bookingSetup();premiumHero('Your travel space','Everything for your next journey.');echo '<div class="metrics">';foreach(['bookings'=>'My bookings','travelhub'=>'Checklist & announcements','growth'=>'Document vault','concierge'=>'Concierge','departures'=>'Explore departures'] as $p=>$label){echo '<article>';premiumLink('?page='.$p,$label);echo '</article>';}echo '</div>';foreach(q('SELECT b.*,t.title,t.itinerary,t.published FROM onb_bookings b JOIN trips t ON t.id=b.trip_id WHERE b.user_id=? ORDER BY b.id DESC',[$u['id']]) as $b){echo '<article><h2>'.h($b['title']).'</h2><p>'.h($b['ref'].' · '.$b['stage']).' · Outstanding CAD '.number_format(max(0,$b['price']-bookingNet($b['id'])),2).'</p>';foreach(q('SELECT due,amount FROM onb_instalments WHERE booking_id=? ORDER BY due',[$b['id']]) as $i)echo '<p>Scheduled: '.h($i['due'].' · CAD '.$i['amount']).'</p>';if(in_array($b['stage'],['confirmed','completed'],true)){echo '<pre>'.h($b['itinerary']).'</pre>';if($b['published'])premiumLink('?page=itinerary-pdf&id='.$b['trip_id'],'Itinerary PDF (if uploaded)');}if($b['stage']==='completed'){form('premium_review');echo '<input type="hidden" name="id" value="'.h($b['id']).'">';field('rating','Rating 1–5','5','number');area('body','Your review');echo '<button>Submit review for moderation</button></form>';}echo '</article>';}echo '<h2>Save journeys</h2>';foreach(q('SELECT t.id,t.title,w.trip_id AS saved FROM trips t LEFT JOIN onb_wishlist w ON w.trip_id=t.id AND w.user_id=? WHERE t.published=1',[$u['id']]) as $t){form('premium_save');echo '<input type="hidden" name="id" value="'.h($t['id']).'"><input type="hidden" name="remove" value="'.($t['saved']?'1':'0').'"><span>'.h($t['title']).'</span><button>'.($t['saved']?'Remove from wishlist':'Save journey').'</button></form>';}}
